     8	
     9	  constructor(graph: Graph, pointers: Pointers) {
    10	    super();
    11	    this._graph = graph;
    12	    this._pointers = pointers;
    13	    return new Proxy(this, {
    14	      apply: (target, _, args: [string]) => {
    15	        const _call = target._call.bind(target);
    16	        return _call(...args);
    17	      },
    18	    });
    19	  }
    20	
    21	  _call(input: string) {
    22	    return this.add(input);
    23	  }
    24	
    25	  __call__(input: string): ParseState {
    26	    return this.add(input);
    27	  }
